$json$::jsonb,
 '2025 Optional State Sales Tax Table, Instructions for Schedule A (2025), irs.gov/instructions/i1040sca, read 2026-10-11. See scripts/431 for shape.')
on conflict (tax_year, key) do update
  set value = excluded.value,
      notes = excluded.notes;

select tax_year, key,
       jsonb_array_length(value->'bands') as bands,
       (select count(*) from jsonb_object_keys(value->'states')) as states,
       value#>>'{states,NV,amounts,18,1}' as nv_300k_family2
  from form_1040_constants
 where key = 'sales_tax_table';

commit;
